import React from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import InputField from '../../../components/ui/InputField/InputField';
import TextareaField from '../../../components/ui/TextareaField/TextareaField';
import Button from '../../../components/ui/Button/Button';
import styles from './SendSocialProofPage.module.css';

const SendSocialProofPage = () => {
  return (
    <ContentWrapper title="Enviar Prova Social">
      <form>
        <InputField label="Título da Ação" name="action_title" placeholder="Ex: Mutirão de Limpeza na Praia" />
        <TextareaField label="Descreva a atividade" name="description" placeholder="Conte como foi a sua participação..." />
        <div>
            <label className={styles.label}>Comprovante</label>
            <div className={styles.fileUpload}>
              <p>Carregar foto ou documento</p>
              <span>PNG, JPG, PDF até 10MB</span>
            </div>
        </div>
        <div style={{maxWidth: '300px', marginTop: '2rem'}}>
            <Button type="submit">Enviar para Análise</Button>
        </div>
      </form>
    </ContentWrapper>
  );
};

export default SendSocialProofPage;
